content:
:root {
  --primary-color: #2b6cb0;
  --primary-hover: #1e4e8c;
  --primary-light: #ebf8ff;
  --bg-gradient: linear-gradient(135deg, #e0f2fe 0%, #ede9fe 50%, #f0fdf4 100%);
  --card-bg: rgba(255, 255, 255, 0.95);
  --card-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.08), 0 8px 10px -6px rgba(0, 0, 0, 0.05);
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;

  --correct-bg: #ecfdf5;
  --correct-border: #10b981;
  --correct-text: #065f46;

  --wrong-bg: #fef2f2;
  --wrong-border: #ef4444;
  --wrong-text: #991b1b;

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Hiragino Sans", "Hiragino Kaku Gothic ProN", Meiryo, sans-serif;
  background: var(--bg-gradient);
  min-height: 100vh;
  color: var(--text-main);
  line-height: 1.6;
  padding: 1.5rem 1rem;
  display: flex;
  justify-content: center;
  align-items: flex-start;
}

.quiz-app {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.quiz-card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  box-shadow: var(--card-shadow);
  padding: 2rem 2.25rem;
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.8);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  transition: var(--transition);
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.header h1 {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.35rem 0.85rem;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  background-color: var(--primary-light);
  color: var(--primary-color);
  border: 1px solid rgba(43, 108, 176, 0.15);
}

.progress-container {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.progress-bar {
  width: 100%;
  height: 8px;
  background-color: #e2e8f0;
  border-radius: var(--radius-full);
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #3182ce, #63b3ed);
  border-radius: var(--radius-full);
  transition: width 0.4s ease-out;
}

.progress-text {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-weight: 500;
  display: flex;
  justify-content: space-between;
}

.question-text {
  font-size: 1.2rem;
  font-weight: 700;
  line-height: 1.5;
  color: var(--text-main);
  padding: 0.25rem 0;
}

.options-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.85rem;
}

.option-btn {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  width: 100%;
  padding: 1rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  border: 2px solid var(--border-color);
  background-color: #ffffff;
  border-radius: var(--radius-md);
  color: var(--text-main);
  cursor: pointer;
  transition: var(--transition);
  position: relative;
  outline: none;
}

.option-btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.option-btn:hover:not(:disabled) {
  border-color: var(--primary-color);
  background-color: var(--primary-light);
  transform: translateY(-1px);
}

.option-btn:disabled {
  cursor: default;
}

.option-btn.option-correct {
  background-color: var(--correct-bg);
  border-color: var(--correct-border);
  color: var(--correct-text);
  box-shadow: 0 0 0 1px var(--correct-border);
}

.option-btn.option-wrong {
  background-color: var(--wrong-bg);
  border-color: var(--wrong-border);
  color: var(--wrong-text);
  box-shadow: 0 0 0 1px var(--wrong-border);
}

.explanation-box {
  background-color: #f8fafc;
  border-left: 4px solid var(--primary-color);
  padding: 1.15rem 1.25rem;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  animation: fadeIn 0.3s ease-out;
}

.explanation-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--primary-color);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.explanation-text {
  font-size: 0.925rem;
  color: #334155;
  line-height: 1.6;
}

.action-btn {
  align-self: flex-end;
  padding: 0.85rem 1.75rem;
  font-size: 1rem;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--primary-color);
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(43, 108, 176, 0.25);
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  outline: none;
}

.action-btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.action-btn:hover {
  background-color: var(--primary-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(43, 108, 176, 0.35);
}

.action-btn:active {
  transform: translateY(0);
}

/* 結果画面のスタイル */
.result-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1.75rem;
  padding: 0.5rem 0;
}

.score-circle {
  width: 150px;
  height: 150px;
  border-radius: var(--radius-full);
  background: linear-gradient(135deg, #ebf8ff 0%, #e0e7ff 100%);
  border: 4px solid var(--primary-color);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8px 20px rgba(43, 108, 176, 0.15);
  animation: popIn 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.score-number {
  font-size: 3rem;
  font-weight: 800;
  color: var(--primary-color);
  line-height: 1;
}

.score-total {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-muted);
}

.score-comment {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  max-width: 480px;
}

.review-list {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  text-align: left;
  margin-top: 0.5rem;
}

.review-title {
  font-size: 1.1rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--text-main);
}

.review-item {
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.15rem;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.review-q {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-main);
}

.review-ans {
  font-size: 0.9rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.review-user-ans {
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.review-user-ans-correct,
.review-user-ans.is-correct {
  color: var(--correct-text);
}

.review-user-ans-wrong,
.review-user-ans.is-wrong {
  color: var(--wrong-text);
}

.review-exp {
  font-size: 0.85rem;
  color: #475569;
  background-color: #ffffff;
  padding: 0.65rem 0.85rem;
  border-radius: var(--radius-sm);
  border-left: 3px solid #94a3b8;
  line-height: 1.5;
}

.restart-btn {
  padding: 0.9rem 2.25rem;
  font-size: 1.05rem;
  font-weight: 700;
  color: #ffffff;
  background: linear-gradient(135deg, #2b6cb0 0%, #3182ce 100%);
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(43, 108, 176, 0.3);
  transition: var(--transition);
  margin-top: 0.5rem;
  outline: none;
}

.restart-btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.restart-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(43, 108, 176, 0.4);
}

.restart-btn:active {
  transform: translateY(0);
}

.restart-icon {
  display: inline;
  margin-right: 6px;
  vertical-align: middle;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes popIn {
  0% {
    opacity: 0;
    transform: scale(0.7);
  }
  70% {
    transform: scale(1.05);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

/* レスポンシブ対応 */
@media (max-width: 480px) {
  body {
    padding: 0.75rem 0.5rem;
  }

  .quiz-card {
    padding: 1.35rem 1.15rem;
    gap: 1.15rem;
    border-radius: var(--radius-md);
  }

  .header h1 {
    font-size: 1.15rem;
  }

  .question-text {
    font-size: 1.05rem;
  }

  .option-btn {
    padding: 0.85rem 1rem;
    font-size: 0.95rem;
  }

  .score-circle {
    width: 125px;
    height: 125px;
  }

  .score-number {
    font-size: 2.5rem;
  }

  .score-comment {
    font-size: 1.1rem;
  }

  .action-btn,
  .restart-btn {
    width: 100%;
    justify-content: center;
  }
}

export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  answerIndex: number;
  explanation: string;
  category?: string;
  difficulty?: 'easy' | 'medium' | 'hard';
}

export interface UserAnswer {
  questionId: number;
  selectedIndex: number;
  isCorrect: boolean;
}

export interface QuizResult {
  score: number;
  totalQuestions: number;
  answers: UserAnswer[];
}

import React, { useState, useMemo } from 'react';
import { quizQuestions } from './data/quizData';
import { QuizQuestion, UserAnswer } from './types';

const TOTAL_QUESTIONS = 5;

// クイズ問題をシャッフルして指定問題数を取得する関数
const getRandomQuestions = (questions: QuizQuestion[], count: number): QuizQuestion[] => {
  const shuffled = [...questions].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
};

const App: React.FC = () => {
  const [questions, setQuestions] = useState<QuizQuestion[]>(() =>
    getRandomQuestions(quizQuestions, TOTAL_QUESTIONS)
  );
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [answers, setAnswers] = useState<UserAnswer[]>([]);
  const [isCompleted, setIsCompleted] = useState<boolean>(false);

  const currentQuestion = questions[currentIndex];

  const handleSelectOption = (index: number) => {
    if (selectedOption !== null) return;

    setSelectedOption(index);
    const isCorrect = index === currentQuestion.answerIndex;
    const newAnswer: UserAnswer = {
      questionId: currentQuestion.id,
      selectedIndex: index,
      isCorrect,
    };
    setAnswers((prev) => [...prev, newAnswer]);
  };

  const handleNext = () => {
    if (currentIndex + 1 < questions.length) {
      setCurrentIndex((prev) => prev + 1);
      setSelectedOption(null);
    } else {
      setIsCompleted(true);
    }
  };

  const handleRestart = () => {
    setQuestions(getRandomQuestions(quizQuestions, TOTAL_QUESTIONS));
    setCurrentIndex(0);
    setSelectedOption(null);
    setAnswers([]);
    setIsCompleted(false);
  };

  const score = useMemo(() => {
    return answers.filter((ans) => ans.isCorrect).length;
  }, [answers]);

  const scoreComment = useMemo(() => {
    if (score === TOTAL_QUESTIONS) return '全問正解！日本の地理マスターです！';
    if (score >= 4) return '素晴らしい！日本地理にとても詳しいですね。';
    if (score >= 3) return '合格ライン！あと少しでマスターレベルです。';
    if (score >= 1) return 'もう一息！復習して再挑戦してみましょう。';
    return '惜しい！解説を読んで再チャレンジしてみてください！';
  }, [score]);

  const progressPercent = Math.round(((currentIndex + (selectedOption !== null ? 1 : 0)) / TOTAL_QUESTIONS) * 100);

  // 選択肢のクラス名を判定
  const getOptionClassName = (index: number): string => {
    if (selectedOption === null) {
      return 'option-btn';
    }
    if (index === currentQuestion.answerIndex) {
      return 'option-btn option-correct';
    }
    if (index === selectedOption) {
      return 'option-btn option-wrong';
    }
    return 'option-btn';
  };

  return (
    <div className="quiz-app">
      <div className="quiz-card">
        <header className="header">
          <h1>
            <span>🗾</span>
            <span>日本地理クイズ</span>
          </h1>
          <span className="badge">
            {isCompleted ? '結果発表' : `第 ${currentIndex + 1} 問 / 全 ${TOTAL_QUESTIONS} 問`}
          </span>
        </header>

        {!isCompleted ? (
          <>
            <div className="progress-container">
              <div className="progress-bar" role="progressbar" aria-valuenow={progressPercent} aria-valuemin={0} aria-valuemax={100}>
                <div
                  className="progress-fill"
                  style={{ width: `${((currentIndex + 1) / TOTAL_QUESTIONS) * 100}%` }}
                />
              </div>
              <div className="progress-text">
                <span>進捗状況</span>
                <span>{currentIndex + 1} / {TOTAL_QUESTIONS}</span>
              </div>
            </div>

            <main>
              <h2 className="question-text">{currentQuestion.question}</h2>

              <div
                className="options-grid"
                role="radiogroup"
                aria-label="クイズの選択肢"
              >
                {currentQuestion.options.map((option, index) => {
                  const isSelected = selectedOption === index;
                  return (
                    <button
                      key={index}
                      type="button"
                      role="radio"
                      aria-checked={isSelected}
                      disabled={selectedOption !== null}
                      onClick={() => handleSelectOption(index)}
                      className={getOptionClassName(index)}
                    >
                      <span>{index + 1}. </span>
                      <span>{option}</span>
                    </button>
                  );
                })}
              </div>

              {selectedOption !== null && (
                <>
                  <div className="explanation-box" role="region" aria-live="polite">
                    <span className="explanation-title">
                      {selectedOption === currentQuestion.answerIndex ? '⭕ 正解！' : '❌ 不正解...'} 解説
                    </span>
                    <p className="explanation-text">{currentQuestion.explanation}</p>
                  </div>

                  <button
                    type="button"
                    className="action-btn"
                    onClick={handleNext}
                  >
                    {currentIndex + 1 < TOTAL_QUESTIONS ? '次の問題へ ➔' : '結果を見る ➔'}
                  </button>
                </>
              )}
            </main>
          </>
        ) : (
          <div className="result-container">
            <div className="score-circle">
              <span className="score-number">{score}</span>
              <span className="score-total">/ {TOTAL_QUESTIONS} 問</span>
            </div>

            <p className="score-comment">{scoreComment}</p>

            <section className="review-list" aria-label="クイズの振り返り">
              <h2 className="review-title">
                <span>📝</span>
                <span>解答の振り返り</span>
              </h2>

              {questions.map((q, idx) => {
                const userAns = answers.find((ans) => ans.questionId === q.id);
                const isCorrect = userAns ? userAns.isCorrect : false;
                const userChoice = userAns !== undefined ? q.options[userAns.selectedIndex] : '未回答';

                return (
                  <div key={q.id} className="review-item">
                    <p className="review-q">
                      <span>第{idx + 1}問: </span>
                      <span>{q.question}</span>
                    </p>
                    <div className="review-ans">
                      <span className={isCorrect ? 'review-user-ans review-user-ans-correct' : 'review-user-ans review-user-ans-wrong'}>
                        あなたの回答: {userChoice} {isCorrect ? '⭕' : '❌'}
                      </span>
                      {!isCorrect && (
                        <span>
                          正解: <strong>{q.options[q.answerIndex]}</strong>
                        </span>
                      )}
                    </div>
                    <div className="review-exp">
                      <span>{q.explanation}</span>
                    </div>
                  </div>
                );
              })}
            </section>

            <button
              type="button"
              className="restart-btn"
              onClick={handleRestart}
            >
              <span className="restart-icon">🔄</span>
              <span>もう一度挑戦する</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;
